select sif.inventory_flow_id, sif.shop_id, sif.put_storage_id, sif.out_storage_id, sif.type, sif.type_details, sif.start_time, sif.end_time, sif.operator_id, sif.operator_name, sif.operator_time, sif.create_time, sif.inventory_flow_num, sif.notes from storage_inventory_flow sif left join storage_inventory_flow_goods sifg on sifg.inventory_flow_id = sif.inventory_flow_id where sif.shop_id = #{param.shopId} and sif.type = #{param.type}
and sif.inventory_flow_id = #{param.inventoryFlowId}
and sif.type_details = #{param.typeDetails}
#{storageId}
#{storageId}
and sifg.goods_id not in
#{goodsId}
and sif.operator_time between #{param.startTime} and #{param.endTime}
group by sif.inventory_flow_id
